// Integrate orphan materials into main material database
(function integrateOrphanMaterials() {
    console.log('[PRISM v8.61.026] Integrating 322 orphan material arrays...');

    // If PRISM_MATERIALS_MASTER exists, add to it
    if (typeof PRISM_MATERIALS_MASTER !== 'undefined') {
        const categorize = (id) => {
            const mid = id.toLowerCase();
            if (mid.startsWith('c') && mid.length >= 5 && /\d/.test(mid[1])) return 'GROUP_N_NONFERROUS';
            if (mid.includes('inconel') || mid.includes('hastelloy') || mid.includes('nimonic')) return 'GROUP_S_SUPERALLOYS';
            if (mid.startsWith('ti') || mid.includes('titanium')) return 'GROUP_S_SUPERALLOYS';
            if (/^[0-9]/.test(mid)) return 'GROUP_N_NONFERROUS';  // Aluminum
            return 'GROUP_P_STEEL';
        };
        for (const [id, name, tensile, yld, hardness, machinability] of PRISM_ORPHAN_MATERIALS_FIX) {
            const group = categorize(id);
            if (PRISM_MATERIALS_MASTER[group] && PRISM_MATERIALS_MASTER[group].grades) {
                PRISM_MATERIALS_MASTER[group].grades[id] = {
                    id, name, tensile, yield: yld, hardness, machinability
                };
            }
            if (PRISM_MATERIALS_MASTER.byId) {
                PRISM_MATERIALS_MASTER.byId[id] = {
                    id, name, tensile, yield: yld, hardness, machinability
                };
            }
        }
        // Update total count
        if (PRISM_MATERIALS_MASTER.byId) {
            PRISM_MATERIALS_MASTER.totalMaterials = Object.keys(PRISM_MATERIALS_MASTER.byId).length;
        }
    }
    console.log('[PRISM v8.61.026] Orphan materials integrated successfully!');
    console.log('[PRISM v8.61.026] Total materials now: ' + (typeof PRISM_MATERIALS_MASTER !== 'undefined' ? PRISM_MATERIALS_MASTER.totalMaterials : 'N/A'));
})();

