    const square = [
      { x: 0, y: 0 },
      { x: 10, y: 0 },
      { x: 10, y: 10 },
      { x: 0, y: 10 }
    ];

    const triangles = PRISM_BREP_TESSELLATOR.earClipTriangulate(square);

    // Should produce 2 triangles
    const passed = triangles.length === 2;

    console.log(`  Generated ${triangles.length} triangles from square`);
    console.log(`  ${passed ? '✅ PASSED' : '❌ FAILED'}`);

    return { name: 'Ear Clipping Triangulation', passed };
