    const inside = PRISM_BREP_TESSELLATOR.pointInTriangle({ x: 5, y: 3 }, a, b, c);
    const outside = PRISM_BREP_TESSELLATOR.pointInTriangle({ x: 0, y: 10 }, a, b, c);

    const passed = inside && !outside;

    console.log(`  Center point inside: ${inside}`);
