                Ceramic: { sfm: Math.round(t.sfm_carbide * mf * 1.6), m_min: Math.round(t.sfm_carbide * mf * 1.6 * 0.305) },
                CBN: { sfm: Math.round(t.sfm_carbide * mf * 2.5), m_min: Math.round(t.sfm_carbide * mf * 2.5 * 0.305) }
